const SVGNS = 'http://www.w3.org/2000/svg';

/**
 * Create an element.
 *
 * @param {string} tag tag name, optionally with .classes and #id, e.g. "button.fg-btn.is-primary"
 * @param {Object|null} attrs attributes; "on*" functions become listeners; "dataset" object; "style" object
 * @param {...*} children strings, nodes, arrays, null
 * @returns {HTMLElement}
 */
export const h = (tag, attrs, ...children) => {
    const parts = tag.split(/(?=[.#])/);
    const el = document.createElement(parts[0] || 'div');
    parts.slice(1).forEach(p => {
        if (p[0] === '.') {
            el.classList.add(p.slice(1));
        } else if (p[0] === '#') {
            el.id = p.slice(1);
        }
    });
    applyAttrs(el, attrs);
    append(el, children);
    return el;
};

/**
 * Create an SVG element.
 *
 * @param {string} tag
 * @param {Object} attrs
 * @param {...*} children
 * @returns {SVGElement}
 */
export const s = (tag, attrs, ...children) => {
    const el = document.createElementNS(SVGNS, tag);
    Object.entries(attrs || {}).forEach(([k, v]) => {
        if (v === null || v === undefined || v === false) {
            return;
        }
        if (k.startsWith('on') && typeof v === 'function') {
            el.addEventListener(k.slice(2).toLowerCase(), v);
        } else {
            el.setAttribute(k, v);
        }
    });
    append(el, children);
    return el;
};

/**
 * Apply attributes.
 *
 * @param {HTMLElement} el
 * @param {Object|null} attrs
 */
const applyAttrs = (el, attrs) => {
    Object.entries(attrs || {}).forEach(([k, v]) => {
        if (v === null || v === undefined || v === false) {
            return;
        }
        if (k.startsWith('on') && typeof v === 'function') {
            el.addEventListener(k.slice(2).toLowerCase(), v);
        } else if (k === 'dataset') {
            Object.assign(el.dataset, v);
        } else if (k === 'style' && typeof v === 'object') {
            Object.assign(el.style, v);
        } else if (k === 'class') {
            String(v).split(/\s+/).filter(Boolean).forEach(c => el.classList.add(c));
        } else if (k === 'html') {
            el.innerHTML = v;
        } else if (k === 'text') {
            el.textContent = v;
        } else if (k in el && typeof v !== 'string' && k !== 'list') {
            el[k] = v;
        } else if (v === true) {
            el.setAttribute(k, '');
        } else {
            el.setAttribute(k, v);
        }
    });
};

/**
 * Append children.
 *
 * @param {Element} el
 * @param {Array} children
 */
export const append = (el, children) => {
    children.flat(Infinity).forEach(c => {
        if (c === null || c === undefined || c === false) {
            return;
        }
        el.appendChild(c instanceof Node ? c : document.createTextNode(String(c)));
    });
};

/**
 * Remove all children and add new ones.
 *
 * @param {Element} el
 * @param {...*} children
 * @returns {Element}
 */
export const replace = (el, ...children) => {
    while (el.firstChild) {
        el.removeChild(el.firstChild);
    }
    append(el, children);
    return el;
};

/**
 * Debounce.
 *
 * @param {Function} fn
 * @param {number} ms
 * @returns {Function}
 */
export const debounce = (fn, ms) => {
    let t = null;
    const d = (...args) => {
        clearTimeout(t);
        t = setTimeout(() => fn(...args), ms);
    };
    d.flush = (...args) => {
        clearTimeout(t);
        fn(...args);
    };
    d.cancel = () => clearTimeout(t);
    return d;
};

/**
 * A short random id.
 *
 * @returns {string}
 */
export const uid = () => 'a' + Date.now().toString(36) + Math.random().toString(36).slice(2, 9);

/**
 * Strip HTML to text.
 *
 * @param {string} html
 * @returns {string}
 */
export const textOf = html => {
    const d = document.createElement('div');
    d.innerHTML = html || '';
    return d.textContent || '';
};

/**
 * Escape text for HTML.
 *
 * @param {string} t
 * @returns {string}
 */
export const esc = t => String(t ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;',
    "'": '&#39;'}[c]));

/**
 * Count words.
 *
 * @param {string} text
 * @returns {number}
 */
export const words = text => (String(text || '').trim().match(/[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu) || []).length;

/**
 * Format seconds as "2d 4h" style.
 *
 * @param {number} secs
 * @returns {string}
 */
export const duration = secs => {
    const d = Math.floor(secs / 86400);
    const hrs = Math.floor((secs % 86400) / 3600);
    const m = Math.floor((secs % 3600) / 60);
    if (d) {
        return `${d}d ${hrs}h`;
    }
    if (hrs) {
        return `${hrs}h ${m}m`;
    }
    return `${Math.max(1, m)}m`;
};

/**
 * Format a timestamp.
 *
 * @param {number} ts seconds
 * @param {boolean} withTime
 * @returns {string}
 */
export const date = (ts, withTime = true) => {
    if (!ts) {
        return '';
    }
    const opts = withTime ? {day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit'} :
        {day: 'numeric', month: 'short', year: 'numeric'};
    return new Date(ts * 1000).toLocaleString(document.documentElement.lang || undefined, opts);
};

